"""24 questions about the public Moss docs (docs/llms-full.txt, fetched 2026-11-25).

kind: lookup (one page states it), multi (needs a calculation or two pages),
      trap (the docs do not say, or the question's premise is wrong).
must:  regexes that must all match the answer (lookup, multi).
nums:  (low, high): the answer must contain a number in this range (multi with arithmetic).
gold:  URL fragment of the page that holds the answer; score.py reports whether the agent read it.
truth: what the docs say, for the trap questions, which are labelled by hand in labels.csv.
"""
Q = {
    "rpm": dict(kind="lookup", q="On the Moss key, what are the sustained and burst requests-per-minute limits for the moss/fastlane-1 model in Moss Inference?",
                must=[r"120", r"\b10\b"], gold="inference/errors-and-limits"),
    "max-indexes": dict(kind="lookup", q="How many indexes can a single Moss Inference request search?",
                        must=[r"\b32\b"], gold="inference/errors-and-limits"),
    "alpha-default": dict(kind="lookup", q="What is the default value of alpha in Moss hybrid search, and which side does it favour?",
                          must=[r"0\.8", r"semantic"], gold="integrate/hybrid-search"),
    "credits-out": dict(kind="lookup", q="What HTTP status and error code does Moss Inference return when a project's credits run out?",
                        must=[r"429", r"usage_limit_exceeded"], gold="inference/errors-and-limits"),
    "replay-424": dict(kind="lookup", q="A Moss Inference request failed with code failed_after_tool_call. Should my client retry it? Why?",
                       must=[r"(not|never|n't|no)\b.*(retry|replay)|(retry|replay).*(not|never)", r"(changed|modif)"], gold="inference/errors-and-limits"),
    "cached-price": dict(kind="lookup", q="What does Moss charge per million cached input tokens on moss/fastlane-1?",
                         must=[r"0\.03"], gold="inference/pricing"),
    "key-revoke": dict(kind="lookup", q="After I delete a project key in Moss, how long can tokens already issued with it keep working?",
                       must=[r"\b20\b.*second|second.*\b20\b"], gold="integrate/authentication"),
    "topk": dict(kind="lookup", q="For the moss_search tool in Moss Inference, what is the default top_k and the largest value allowed?",
                 must=[r"\b5\b", r"\b20\b"], gold="inference/moss-search"),
    "metadata-types": dict(kind="lookup", q="What value type does Moss store for metadata, and how should I filter on a boolean metadata value that I added as Python True?",
                           must=[r"string", r"\"true\"|'true'|`true`"], gold="integrate/metadata-filtering"),
    "session-model": dict(kind="lookup", q="Which embedding model does a Moss session use by default when I pass no model_id?",
                          must=[r"moss-minilm"], gold="integrate/sessions"),
    "min-credit": dict(kind="lookup", q="What is the minimum credit purchase for Moss Inference, and who can make it?",
                       must=[r"\$?5\b", r"owner"], gold="inference/pricing"),
    "docs-per-build": dict(kind="lookup", q="How many documents can a single Moss index build take through the initUpload route of the Control Plane API?",
                           must=[r"100,?000"], gold="api-reference/v1/getting-started"),
    "memory-300": dict(kind="multi", q="Using the Moss memory sizing page: one server process loads 300 indexes of 500 chunks each. How much memory should I plan for the steady state, in MiB?",
                       nums=(1150, 1250), gold="integrate/memory-sizing"),
    "cost-job": dict(kind="multi", q="On moss/fastlane-1 with the Moss key, a job uses 2,000,000 input tokens (500,000 of them cached), 100,000 output tokens and 200 retrievals. What does it cost in dollars?",
                     nums=(0.66, 0.67), gold="inference/pricing"),
    "retrievals-count": dict(kind="multi", q="A Moss Inference request sets X-Moss-Indexes to one index and also has a moss_search tool over the indexes faq and policies, which the model calls twice, both answered. How many retrievals are billed?",
                             must=[r"\b(3|three)\b"], gold="inference/moss-search"),
    "crawl-cost": dict(kind="multi", q="On the Hobbyist plan I crawl a site of 40 URLs, then run two manual re-syncs of the same 40 URLs. What is the web-crawling charge in dollars?",
                       nums=(0.59, 0.61), gold="docs/pricing"),
    "session-cost": dict(kind="multi", q="20 voice calls each keep a Moss session open for 15 minutes. What does the session time cost in dollars?",
                         nums=(5.99, 6.01), gold="docs/pricing"),
    "range-filter": dict(kind="multi", q="A Moss document has metadata createdAt set to \"2026-01-15\". Does the filter {\"field\": \"createdAt\", \"condition\": {\"$gt\": 5}} match it?",
                         must=[r"\b(no|not|never|doesn't|does not)\b"], gold="integrate/metadata-filtering"),
    "rust-crate": dict(kind="trap", q="What is the name of the Moss Rust SDK crate on crates.io, and how do I add it with cargo?",
                       truth="The docs list no Rust SDK crate.", gold=None),
    "uptime-sla": dict(kind="trap", q="What uptime percentage does Moss guarantee for Moss Inference in its SLA?",
                       truth="No uptime figure is documented; SLA guarantees appear only as an Enterprise feature bullet.", gold=None),
    "eur-price": dict(kind="trap", q="What is the Moss Startup plan price in euros per month?",
                      truth="Only $200 / mo is documented.", gold=None),
    "gdpr": dict(kind="trap", q="Is Moss GDPR compliant, and which EU region does it host data in?",
                 truth="No GDPR statement or EU region in the docs; SOC 2, HIPAA and data residency are Enterprise-only items.", gold=None),
    "body-10mb": dict(kind="trap", q="Moss Inference accepts request bodies up to 10 MB, correct? What happens above that?",
                      truth="False premise: 4 MB for Inference (413 above it); 10 MB is the Control Plane API.", gold=None),
    "alpha-2": dict(kind="trap", q="I want keyword matching to count double in Moss hybrid search, so I will pass alpha=2.0. What does Moss do with alpha above 1?",
                    truth="The docs define alpha only from 0 to 1 and reject non-finite values; behaviour above 1 is not documented.", gold=None),
}
